import ast
import operator

def eval_expression(expr):
    # 引数チェック
    if not isinstance(expr, str):
        raise TypeError("引数は文字列である必要があります")

    try:
        tree = ast.parse(expr)

        class ExpressionEvaluator(ast.NodeVisitor):
            def __init__(self):
                self.result = None

            def visit_Constant(self, node):
                self.result = node.value

            def visit_BinOp(self, node):
                left = self.visit(node.left)
                right = self.visit(node.right)

                if isinstance(node.op, ast.Mod):
                    if right == 0:
                        raise ZeroDivisionError("ゼロで割ることはできません")

                op_map = {
                    ast.Add: operator.add,
                    ast.Sub: operator.sub,
                    ast.Mult: operator.mul,
                    ast.Div: operator.truediv,
                    ast.FloorDiv: operator.floordiv,
                    ast.Pow: operator.pow,
                    ast.Mod: lambda x, y: x % y,  # 自前で実装（安全のため）
                }

                if type(node.op) not in op_map:
                    raise ValueError(f"サポートされていない演算子: {type(node.op)}")

                self.result = op_map[type(node.op)](left, right)

            def visit_UnaryOp(self, node):
                operand = self.visit(node.operand)

                if isinstance(node.op, ast.USub):
                    self.result = -operand
                elif isinstance(node.op, ast.UAdd):
                    self.result = +operand
                elif isinstance(node.op, ast.Not):
                    # 論理演算子 NOT はサポートしないため raise
                    raise ValueError("NOT演算はサポートされていません")

            def visit_Compare(self, node):
                raise ValueError("比較演算はサポートされていません")

            def generic_visit(self, node):
                raise TypeError(f"サポートされていない AST ノード: {type(node)}")

        # 式解析と評価の実行
        evaluator = ExpressionEvaluator()
        evaluator.visit(tree)

        if evaluator.result is None:
            raise ValueError("有効な計算式ではありません")

        return evaluator.result

    except ZeroDivisionError:
        raise
    except Exception as e:
        raise RuntimeError(f"式の計算中にエラーが発生しました: {e}")
